#include <stdint.h>
#include <stdio.h>
#include <unistd.h>

int main(void) {
    long system_page_size = sysconf(_SC_PAGESIZE);
    size_t demo_page_size = 4096;

    size_t object_size = 10 * 1024;
    size_t page_count = (object_size + demo_page_size - 1) / demo_page_size;
    size_t internal_waste = page_count * demo_page_size - object_size;

    uintptr_t virtual_address = 0x12345abc;
    uintptr_t vpn = virtual_address / demo_page_size;
    uintptr_t offset = virtual_address % demo_page_size;

    size_t segment_limit = 8192;
    size_t segment_offset = 9000;
    const char *segment_result = segment_offset <= segment_limit ? "ok" : "segmentation fault";

    size_t huge_page = 2 * 1024 * 1024;
    size_t normal_pages_per_huge = huge_page / demo_page_size;

    printf("system page size: %ld bytes\n", system_page_size);
    printf("demo page size: %zu bytes\n", demo_page_size);
    printf("10KiB object uses %zu pages, internal waste=%zu bytes\n", page_count, internal_waste);
    printf("virtual address 0x%lx => VPN=%lu, offset=%lu\n",
           (unsigned long)virtual_address,
           (unsigned long)vpn,
           (unsigned long)offset);
    printf("segment offset=%zu, limit=%zu => %s\n", segment_offset, segment_limit, segment_result);
    printf("2MiB huge page contains %zu normal pages\n", normal_pages_per_huge);

    return page_count == 3 && internal_waste == 2048 && normal_pages_per_huge == 512 ? 0 : 1;
}
